window.addEventListener('profile-change',()=>{if(location.hash==='#perfil'||needsRegistration())render();});
window.addEventListener('active-plan-change',()=>{if(!['#perfil','#prova','#guia'].includes(location.hash))render();});
configureAccountSync({
 capture(owner){const archive=exportPlanArchive();const owned=archive.plans.filter(p=>p.owner===owner),ids=new Set([...SESSIONS,...allGeneratedSessions({plans:owned})].map(s=>s.id));return {version:1,draft:JSON.parse(localStorage.getItem('dez-voltas-draft-v1:'+owner)||'null'),profile:JSON.parse(localStorage.getItem('dez-voltas-profile-v1:'+owner)||'null'),archive:{version:1,owner,plans:owned},state:{...state,logs:Object.fromEntries(Object.entries(state.logs).filter(([id])=>ids.has(id))),timer:null}};},
 select(owner,saved){
  const marker=localStorage.getItem('dez-voltas-legacy-owner');
  if(!marker){localStorage.setItem('dez-voltas-legacy-backup',JSON.stringify({state,archive:exportPlanArchive()}));localStorage.setItem('dez-voltas-legacy-owner',owner);}
  if(saved)this.apply(saved,owner);
  else if(marker&&marker!==owner){state={version:1,logs:{},checklist:{},timer:null};localStorage.setItem(KEY,JSON.stringify(state));}
  else {const allowed=new Set([...SESSIONS,...allGeneratedSessions({plans:exportPlanArchive().plans.filter(p=>p.owner===owner)})].map(s=>s.id));state={...state,logs:Object.fromEntries(Object.entries(state.logs).filter(([id])=>allowed.has(id))),timer:null};}
 },
 apply(doc,owner){
  replaceOwnerArchive(owner,doc.archive);state=cleanState(doc.state);localStorage.setItem(KEY,JSON.stringify(state));
  const dk='dez-voltas-draft-v1:'+owner;if(doc.draft)localStorage.setItem(dk,JSON.stringify(doc.draft));else localStorage.removeItem(dk);
  const k='dez-voltas-profile-v1:'+owner;if(doc.profile)localStorage.setItem(k,JSON.stringify(doc.profile));else localStorage.removeItem(k);
  window.dispatchEvent(new Event('account-data-loaded'));window.dispatchEvent(new Event('active-plan-change'));
 },
 disconnect(){state={version:1,logs:{},checklist:{},timer:null};localStorage.setItem(KEY,JSON.stringify(state));window.dispatchEvent(new Event('active-plan-change'));}
});
